package souther.compiler;

import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** The shapes a block writes a row in, read back as the row they are. */
class RowsOfABlockTest {

    private static final String BLOCK = """
            // generated by `souther examples --generate`: 3 rows to fill what nothing covers.
            // Replace each `<?>` with what the system actually answers.
            example submit
            // fills a decision rule (the comparison at 15:30 does not hold)
            // fills x=1 < x
            // stops at the guard at 0:15:5
                | (Draft { cost = Amount(101) }) -> <?>
            // fills value = 0
            // fills case Off (12:5)
                | "a \\"quoted\\" class" : (Draft { cost = Amount(0) }) -> <?>
            // no row for `x = 4` in `submit`: the search left something untried

            example settle
                | "wrapped"
                    : (Draft { cost = Amount(7) })
                    -> <?>
            """;

    @Test
    void eachRowIsReadWithItsBehaviorItsNameAndWhatIsSaidOverIt() {
        List<RowsOfABlock.Row> rows = RowsOfABlock.of(BLOCK);

        assertEquals(List.of("submit", "submit", "settle"),
                rows.stream().map(RowsOfABlock.Row::behavior).toList());
        assertEquals(List.of(Optional.empty(), Optional.of("a \"quoted\" class"),
                Optional.of("wrapped")), rows.stream().map(RowsOfABlock.Row::name).toList());
        assertEquals(List.of("a decision rule (the comparison at 15:30 does not hold)", "x=1 < x"),
                rows.get(0).fills());
        assertEquals(3, rows.get(0).over().size(), "a stop is said over the row too");
        assertEquals(List.of("value = 0", "case Off (12:5)"), rows.get(1).fills());
        assertEquals(List.of(), rows.get(2).fills(),
                "the note below a block is over no row, and a blank line ends what is over one");
        assertTrue(rows.get(2).written().contains("-> <?>"),
                "a wrapped row is one row: " + rows.get(2).written());
        assertEquals(List.of("(Draft { cost = Amount(101) }) -> <?>",
                        "(Draft { cost = Amount(0) }) -> <?>", "(Draft { cost = Amount(7) }) -> <?>"),
                rows.stream().map(RowsOfABlock.Row::values).toList(),
                "what a row holds and answers is read past its name, wrapped or not");
    }

    @Test
    void whatARowIsForIsReadFromItsNameOrFromOverIt() {
        assertTrue(RowsOfABlock.forThe(BLOCK, "x=1 < x").name().isEmpty());
        assertEquals(Optional.of("wrapped"), RowsOfABlock.forThe(BLOCK, "wrapped").name());
        assertEquals(Optional.of("a \"quoted\" class"), RowsOfABlock.forThe(BLOCK, "case Off").name(),
                "a thing said with its place is the thing its words say");
        assertFalse(RowsOfABlock.of(BLOCK).stream().anyMatch(row -> row.isFor("case O")),
                "and not a thing whose words begin the same");
        assertFalse(RowsOfABlock.of(BLOCK).stream().anyMatch(row -> row.isFor("x = 4")),
                "a thing no row is written for is no row's");
    }

    @Test
    void aRowWrittenNeitherWithANameNorWithNoneIsRefused() {
        assertThrows(AssertionError.class, () -> RowsOfABlock.of("""
                example submit
                    | name : (Draft { cost = Amount(0) }) -> <?>
                """));
    }
}
